function [H11, H22] = dp_hessian(th1, th2, m1, m2, L1, L2, g)
%% DP_HESSIAN  Analytic Hessian of the double-pendulum potential energy.
%%
%%   [H11, H22] = dp_hessian(th1, th2, m1, m2, L1, L2, g)
%%
%%   Returns the diagonal entries of  hess V  where
%%
%%       V = -m1 g L1 cos(th1) - m2 g (L1 cos(th1) + L2 cos(th2))
%%
%%   GENERATED by dp_v2/gen/gen_hessian.py -- do not edit by hand.
%%
%%   The Hessian is DIAGONAL because this potential is separable; the
%%   generator asserts that, so the two-output signature cannot silently
%%   become wrong if V is ever changed.
%%
%%   The off-diagonal entries are therefore zero and are not returned.
%%   Callers build the 2x2 Hessian as  diag([H11, H22])  when they need
%%   the full matrix, e.g. for the double pendulums implicit midpoint
%%   step (dp_implicit_step.m).

    H11 = L1.*g.*(m1 + m2).*cos(th1);
    H22 = L2.*g.*m2.*cos(th2);
end
